CREATE TABLE customers(id INTEGER, name TEXT);
CREATE TABLE orders(id INTEGER, customer_id INTEGER);
INSERT INTO customers VALUES (1,'Ann'), (2,'Bo'), (3,'Cy');
INSERT INTO orders VALUES (1,1), (2,1), (3,2);
SELECT 'inner' AS q, COUNT(*) AS n FROM customers c JOIN orders o ON o.customer_id = c.id;
SELECT 'left' AS q, COUNT(*) AS n FROM customers c LEFT JOIN orders o ON o.customer_id = c.id;

CREATE TABLE customers(id INTEGER, name TEXT);
CREATE TABLE orders(id INTEGER, customer_id INTEGER, total REAL);
INSERT INTO customers VALUES (1,'Cy');
SELECT c.name, o.total FROM customers c LEFT JOIN orders o ON o.customer_id = c.id;

CREATE TABLE sizes(s TEXT);
CREATE TABLE colors(c TEXT);
INSERT INTO sizes VALUES ('S'), ('M'), ('L');
INSERT INTO colors VALUES ('red'), ('blue'), ('green'), ('black');
SELECT s, c FROM sizes CROSS JOIN colors;

CREATE TABLE users(id INTEGER, name TEXT);
CREATE TABLE logins(user_id INTEGER, day TEXT);
INSERT INTO users VALUES (1,'Ann'), (2,'Bo');
INSERT INTO logins VALUES (1,'mon'), (1,'tue'), (1,'wed'), (2,'mon');
SELECT u.name FROM users u JOIN logins l ON l.user_id = u.id;

CREATE TABLE employees(id INTEGER, name TEXT, manager_id INTEGER);
INSERT INTO employees VALUES (1,'Ceo',NULL), (2,'Ann',1), (3,'Bo',2);
SELECT e.name, m.name AS manager FROM employees e JOIN employees m ON m.id = e.manager_id ORDER BY e.name;

CREATE TABLE customers(id INTEGER, name TEXT);
CREATE TABLE orders(id INTEGER, customer_id INTEGER, status TEXT);
INSERT INTO customers VALUES (1,'Ann'), (2,'Bo'), (3,'Cy');
INSERT INTO orders VALUES (1,1,'paid'), (2,2,'refunded');
SELECT c.name, o.id FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id
WHERE o.status = 'paid';

CREATE TABLE orders(id INTEGER, customer_id INTEGER);
CREATE TABLE payments(id INTEGER, customer_id INTEGER, amount REAL);
INSERT INTO orders VALUES (1,1), (2,1);
INSERT INTO payments VALUES (1,1,10), (2,1,10), (3,1,10);
SELECT o.customer_id, SUM(p.amount) AS paid
FROM orders o JOIN payments p ON p.customer_id = o.customer_id
GROUP BY o.customer_id;

CREATE TABLE customers(id INTEGER, name TEXT);
CREATE TABLE orders(id INTEGER, customer_id INTEGER);
INSERT INTO customers VALUES (1,'Cy');
SELECT c.name, COUNT(*) AS n FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id;

CREATE TABLE a(k INTEGER, v TEXT);
CREATE TABLE b(k INTEGER, w TEXT);
INSERT INTO a VALUES (1,'x'), (NULL,'y');
INSERT INTO b VALUES (1,'p'), (NULL,'q');
SELECT a.v, b.w FROM a JOIN b ON b.k = a.k;

CREATE TABLE months(month TEXT);
CREATE TABLE sales(month TEXT, amount REAL);
INSERT INTO months VALUES ('jan'), ('feb');
INSERT INTO sales VALUES ('jan', 5);
SELECT s.month, SUM(s.amount) AS total FROM sales s LEFT JOIN months m ON m.month = s.month GROUP BY s.month;
